import{_ as a,o as n,c as s,a2 as d}from"./chunks/framework.1lR7qgqY.js";const u=JSON.parse('{"title":"第 3 章 地端 AI 分層與預設組合","description":"","frontmatter":{},"headers":[],"relativePath":"intro/03-layers.md","filePath":"intro/03-layers.md","lastUpdated":1793001879000}'),e={name:"intro/03-layers.md"};function l(p,t,r,i,o,c){return n(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="第-3-章-地端-ai-分層與預設組合" tabindex="-1">第 3 章 地端 AI 分層與預設組合 <a class="header-anchor" href="#第-3-章-地端-ai-分層與預設組合" aria-label="Permalink to &quot;第 3 章 地端 AI 分層與預設組合&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ● 必要, 所有讀者都讀</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li></ul></div><p><strong>結論</strong>: 地端 AI 的必要層只有四個: 推論引擎, 使用者介面, 存取控制, 備份與更新. 其餘各層只在特定情境才加入. 預設組合是「推論引擎 + 一個聊天介面 + 只綁本機或私有網路 + 固定版本與備份」(信心: 高, 屬推論, 依據為第 9 至 13 章各元件的漏洞紀錄與資源需求).</p><h2 id="_3-1-分層圖-必要層與依情境層" tabindex="-1">3.1 分層圖: 必要層與依情境層 <a class="header-anchor" href="#_3-1-分層圖-必要層與依情境層" aria-label="Permalink to &quot;3.1 分層圖: 必要層與依情境層&quot;">​</a></h2><p>下圖把必要層放在最下方, 越往上越晚才需要加. 標示 ● 的層是必要層, ○ 是符合條件才加入的層, ◇ 是進階層, 不建議初階讀者加入.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>由上而下, 越上面越晚才需要加:</span></span>
<span class="line"><span></span></span>
<span class="line"><span> ◇ 沙箱層: 模型要執行程式碼時才需要; 一旦需要即屬必要</span></span>
<span class="line"><span> ◇ 工具協定層: MCP (Model Context Protocol)</span></span>
<span class="line"><span> ○ 編排與代理層: 固定工作流程優先, 其次才是代理框架</span></span>
<span class="line"><span> ○ 可觀測層: 測試集必要; 追蹤平台依情境</span></span>
<span class="line"><span> ○ 檢索層: 要「問自己的文件」時才加 (第 12 章)</span></span>
<span class="line"><span> ------------------------------------------------------------</span></span>
<span class="line"><span> ○ 閘道與路由層: 符合第 10.1 節三項條件中的任兩項時 (第 10 章)</span></span>
<span class="line"><span> ○ 模型切換層: 一張顯示卡輪流跑多個模型時 (llama-swap)</span></span>
<span class="line"><span> ------------------------------------------------------------</span></span>
<span class="line"><span> ● 使用者介面層: Open WebUI / LibreChat / AnythingLLM 擇一</span></span>
<span class="line"><span> ● 身分與網路層: 只綁 127.0.0.1, 或走 VPN (Tailscale)</span></span>
<span class="line"><span> ● 機密管理層: .env 檔 + 檔案權限 600</span></span>
<span class="line"><span> ● 備份與更新層: 鎖定版本, 每週備份資料卷 (第 18, 19 章)</span></span>
<span class="line"><span> ● 推論層: llama.cpp / Ollama / LM Studio (第 8 章)</span></span></code></pre></div><p>另有兩層不建議單獨加入: 護欄層 (guardrail) 與 Kubernetes. 原因見 3.3.</p><h2 id="_3-2-各層的必要性判斷" tabindex="-1">3.2 各層的必要性判斷 <a class="header-anchor" href="#_3-2-各層的必要性判斷" aria-label="Permalink to &quot;3.2 各層的必要性判斷&quot;">​</a></h2><table tabindex="0"><thead><tr><th>層</th><th>分級</th><th>判斷依據</th></tr></thead><tbody><tr><td>推論層</td><td>必要</td><td>沒有推論引擎就沒有服務</td></tr><tr><td>使用者介面層</td><td>必要</td><td>Open WebUI, LibreChat, AnythingLLM 擇一 (信心: 高)</td></tr><tr><td>身分與存取 / 網路層</td><td>必要</td><td>最小做法是只綁 localhost 或 VPN, 不必上 SSO (信心: 高)</td></tr><tr><td>備份與更新層</td><td>必要</td><td>地端最常被忽略的必要層 (信心: 高)</td></tr><tr><td>機密管理層</td><td>必要, 最低限度</td><td><code>.env</code> 檔加權限 600 即可; Vault 或 OpenBao 對多數讀者過度 (信心: 中高, 屬推論)</td></tr><tr><td>檢索層 (RAG)</td><td>依情境</td><td>有「問自己文件」的需求才加 (信心: 高)</td></tr><tr><td>模型切換層</td><td>依情境</td><td>需要多個模型輪流佔用顯示記憶體時才加 llama-swap (信心: 中高)</td></tr><tr><td>閘道與路由層</td><td>依情境, 多人</td><td>符合第 10.1 節三項條件中的任兩項 (多人個別金鑰與配額, 混用雲端與地端, 多應用統一入口) 才加 (信心: 高)</td></tr><tr><td>可觀測性與評估層</td><td>評估必要, 追蹤依情境</td><td>一份回歸測試集是必要的; Langfuse 這類追蹤平台依情境 (信心: 中高)</td></tr><tr><td>編排與代理層</td><td>依情境</td><td>多數讀者用固定工作流程即可 (信心: 中高)</td></tr><tr><td>工具協定層 (MCP)</td><td>依情境, 進階</td><td>需要跨客戶端重用工具時才加 (信心: 中高)</td></tr><tr><td>沙箱層</td><td>依情境</td><td>只要讓模型執行程式碼就變成必要 (信心: 高)</td></tr><tr><td>護欄層</td><td>不建議單獨加</td><td>地端單人情境成本效益低, 權限設計比護欄模型更有效 (信心: 中)</td></tr><tr><td>Kubernetes</td><td>不建議</td><td>單機無法發揮排程與高可用的價值 (信心: 中高, 屬推論)</td></tr></tbody></table><p>資料來源: 研究 2《地端 AI 完整架構權衡研究》(2026-10-26), 分級與信心水準為該研究的整理判斷.</p><h2 id="_3-3-「少而精」的判斷原則" tabindex="-1">3.3 「少而精」的判斷原則 <a class="header-anchor" href="#_3-3-「少而精」的判斷原則" aria-label="Permalink to &quot;3.3 「少而精」的判斷原則&quot;">​</a></h2><p>2026 年的主要風險不在模型, 而在推論引擎之上的中介層. 閘道 (LiteLLM), 低程式碼平台 (Langflow, n8n, Flowise) 與 MCP 實作都出現過已被實際利用的漏洞 (信心: 高, 依據為 CISA KEV, VulnCheck 與各廠商通報; 細節見第 10, 11, 13 章). 這類服務的共同點是同時保存金鑰, 又能執行程式碼, 因此一旦被入侵, 影響範圍大於單一應用程式.</p><p>本手冊據此採用三條取捨原則:</p><ol><li><strong>能不加就不加</strong>: 每多一層, 就多一個要更新, 備份與監看公告的服務. 若無法每週檢查安全公告, 寧可少裝元件.</li><li><strong>先固定流程, 再考慮自主代理</strong>: 小模型單步工具呼叫約 78% 至 88%, 多輪任務只有約 30% 至 42% (BFCL V4, 第 13 章).</li><li><strong>權限設計優先於偵測</strong>: 不給模型不需要的工具權限, 寫入與刪除需要人工確認, 比加護欄模型更有效.</li></ol><h3 id="讀者怎麼用這張圖" tabindex="-1">讀者怎麼用這張圖 <a class="header-anchor" href="#讀者怎麼用這張圖" aria-label="Permalink to &quot;讀者怎麼用這張圖&quot;">​</a></h3><ul><li>等級 A 至 B 的讀者: 只看 ● 層, 照第 9.1 節的最小組合架設.</li><li>等級 C 至 E 的讀者: 在 ● 層之上, 依需求挑選 ○ 層, 照第 9.2 節的標準組合架設.</li><li>等級 F, 符合第 10.1 節閘道條件且有人每週維運的讀者: 才需要閱讀 ◇ 層與第 9.3 節.</li></ul>`,16)])])}const b=a(e,[["render",l]]);export{u as __pageData,b as default};
